  font-size: 13px;
  transform-origin: var(
    --radix-popper-transform-origin,
    var(--radix-dropdown-menu-content-transform-origin, center)
  );
}
[data-side='top'] {
  --enter-y: 6px;
}
[data-side='left'] {
  --enter-x: 6px;
  --enter-y: 0px;
}
[data-side='right'] {
  --enter-x: -6px;
  --enter-y: 0px;
}
[data-slot='popover-content'],
[data-slot='hover-card-content'] {
  padding: 16px;
}
[data-slot='select-content'] {
  min-width: var(--radix-select-trigger-width);
}
[data-slot='dropdown-menu-item'],
[data-slot='context-menu-item'],
[data-slot='select-item'],
[data-slot='menubar-item'],
[data-slot='command-item'] {
  border-radius: 10px;
  font-size: 13px;
  min-height: 34px;
  padding-inline: 10px;
  transition:
    background var(--duration-quick),
    color var(--duration-quick);
}
[data-slot='dropdown-menu-item'][data-highlighted],
[data-slot='context-menu-item'][data-highlighted],
[data-slot='select-item'][data-highlighted],
[data-slot='menubar-item'][data-highlighted],
[data-slot='command-item'][data-selected='true'] {
  background: var(--secondary);
  color: var(--foreground);
}
[data-slot='dropdown-menu-item'] svg,
[data-slot='context-menu-item'] svg,
[data-slot='command-item'] svg {
  color: var(--muted-foreground);
}
[data-slot='dropdown-menu-shortcut'],
[data-slot='context-menu-shortcut'],
[data-slot='menubar-shortcut'] {
  font-size: 11px;
  letter-spacing: 0.04em;
}
[data-slot='dropdown-menu-separator'],
[data-slot='context-menu-separator'],
[data-slot='menubar-separator'] {
  margin: 4px 6px;
  background: var(--border);
}
[data-slot='dropdown-menu-label'] {
  font-size: 11px;
  font-weight: 500;
  color: var(--muted-foreground);
  padding: 6px 10px 4px;
}
[data-slot='popover-content'][data-state='open'],
[data-slot='dropdown-menu-content'][data-state='open'],
[data-slot='select-content'][data-state='open'],
[data-slot='context-menu-content'][data-state='open'],
[data-slot='hover-card-content'][data-state='open'],
[data-slot='menubar-content'][data-state='open'] {
  animation: material-enter var(--duration-fast) var(--ease-out);
}
[data-slot='popover-content'][data-state='closed'],
[data-slot='dropdown-menu-content'][data-state='closed'],
[data-slot='select-content'][data-state='closed'],
[data-slot='context-menu-content'][data-state='closed'],
[data-slot='hover-card-content'][data-state='closed'],
[data-slot='menubar-content'][data-state='closed'] {
  animation: material-exit var(--duration-quick) var(--ease-out) forwards;
}
[data-slot='dialog-content'][data-state='open'],
[data-slot='alert-dialog-content'][data-state='open'] {
  animation: dialog-enter 300ms var(--ease-out);
}
[data-slot='dialog-content'][data-state='closed'],
[data-slot='alert-dialog-content'][data-state='closed'] {
  animation: dialog-exit var(--duration-quick) var(--ease-out) forwards;
}
[data-slot='tooltip-content'] {
  border-radius: 8px;
  padding: 6px 9px;
  font-size: 12px;
  font-weight: 500;
  box-shadow:
    0 4px 14px rgba(0, 0, 0, 0.18),
    0 0 0 1px rgba(0, 0, 0, 0.04);
}
[data-slot='tooltip-content'] {
  transform-origin: var(--radix-tooltip-content-transform-origin);
}
[data-slot='tooltip-content'][data-state='delayed-open'] {
  animation: tooltip-enter 125ms var(--ease-out);
}
[data-slot='tooltip-content'][data-state='instant-open'] {
  animation: none;
}

/* Composite surfaces */
[data-slot='command'],
[data-slot='menubar'],
[data-slot='scroll-area'],
[data-slot='resizable-panel-group'] {
  background: var(--surface);
  border-radius: 16px;
  box-shadow: var(--material-shadow);
  border-color: transparent;
}
[data-slot='command-input-wrapper'] {
  border-bottom: 1px solid var(--border);
  margin-bottom: 4px;
}
[data-slot='command-input'] {
  font-size: 13px;
}
[data-slot='command-group'] [cmdk-group-heading] {
  font-size: 11px;
  font-weight: 500;
  color: var(--muted-foreground);
  padding: 6px 10px 4px;
}
[data-slot='menubar'] {
  height: 40px;
  padding: 4px;
  gap: 2px;
  border-radius: 99px;
}
[data-slot='menubar-trigger'] {
  font-size: 13px;
  font-weight: 500;
  padding: 5px 12px;
  border-radius: 99px;
  transition: background var(--duration-quick);
}
[data-slot='menubar-trigger']:hover,
[data-slot='menubar-trigger'][data-state='open'] {
  background: var(--secondary);
}
[data-slot='navigation-menu-trigger'],
[data-slot='navigation-menu-link'] {
  font-size: 13px;
  font-weight: 500;
  border-radius: 99px;
  transition: background var(--duration-quick);
}
[data-slot='navigation-menu-content'] [data-slot='navigation-menu-link'] {
  border-radius: 10px;
}
[data-slot='navigation-menu-viewport'] {
  border-radius: 16px;
  border-color: transparent;
  box-shadow: var(--overlay-shadow);
}
[data-slot='breadcrumb-list'] {
  font-size: 13px;
  gap: 6px;
}
[data-slot='breadcrumb-link'] {
  transition: color var(--duration-quick);
}
[data-slot='breadcrumb-page'] {
  font-weight: 500;
  padding: 3px 10px;
  border-radius: 99px;
  background: var(--surface);
  box-shadow: var(--material-shadow);
}
[data-slot='pagination-link'] {
  transition:
    background var(--duration-fast),
    box-shadow var(--duration-fast),
    transform var(--duration-quick) var(--ease-out);
}
[data-slot='pagination-link'][data-active='true'] {
  background: var(--foreground) !important;
  color: var(--background) !important;
  box-shadow: 0 4px 12px -4px rgba(0, 0, 0, 0.3);
}
[data-slot='pagination-link']:active {
  transform: scale(0.94);
}
[data-slot='resizable-handle'] {
  background: var(--border);
  transition: background var(--duration-fast);
}
[data-slot='resizable-handle']:hover,
[data-slot='resizable-handle'][data-separator='active'] {
  background: var(--primary-bright);
}
[data-slot='resizable-handle'] > div {
  width: 6px;
  height: 28px;
  background: var(--surface);
  box-shadow: var(--material-shadow);
}
[data-slot='scroll-area-thumb'] {
  background: color-mix(in srgb, var(--foreground) 18%, transparent);
}
[data-slot='input-otp-group'] {
  gap: 8px;
}
[data-slot='input-otp-slot'] {
  width: 42px;
  height: calc(var(--field-h) + 8px);
  font-size: calc(var(--field-font) + 4px);
  font-weight: 600;
  border: 1px solid var(--input) !important;
  border-radius: var(--field-radius) !important;
  background: var(--surface);
  box-shadow: 0 1px 2px rgba(28, 20, 10, 0.04);
  transition:
    border-color var(--duration-quick),
    box-shadow var(--duration-fast),
    transform var(--duration-quick) var(--ease-out);
}
[data-slot='input-otp-slot'][data-active='true'] {
  border-color: var(--ring) !important;
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--ring) 16%, transparent);
  transform: translateY(-2px);
  z-index: 1;
}
[data-slot='skeleton'] {
  background: linear-gradient(
    100deg,
    color-mix(in srgb, var(--foreground) 6%, transparent) 30%,
    color-mix(in srgb, var(--foreground) 11%, transparent) 50%,
    color-mix(in srgb, var(--foreground) 6%, transparent) 70%
  );
  background-size: 200% 100%;
  animation: skeleton-sheen 1.8s ease-in-out infinite;
}
[data-slot='calendar'] {
  --cell-size: 34px;
  border-color: transparent !important;
  border-radius: 18px;
  background: var(--surface);
  box-shadow: var(--material-shadow);
  font-size: 12px;
  padding: 12px;
}
[data-slot='calendar'] .rdp-month_caption,
[data-slot='calendar'] [class*='caption_label'] {
  font-size: 13px;
  font-weight: 600;
}
[data-slot='calendar'] .rdp-weekday,
[data-slot='calendar'] [class*='weekday'] {
  font-size: 11px;
}
[data-slot='calendar'] button[data-day] {
  border-radius: 10px;
  font-size: 12px;
  transition:
    background var(--duration-quick),
    transform var(--duration-quick) var(--ease-out);
}
[data-slot='calendar'] button[data-day]:active {
  transform: scale(0.9);
}
[data-slot='calendar'] button[data-selected-single='true'] {
  background: var(--primary);
  color: var(--primary-foreground);
  box-shadow: 0 4px 10px -3px
    color-mix(in srgb, var(--primary) 60%, transparent);
}
[data-slot='popover-content'] [data-slot='calendar'] {
  box-shadow: none;
}
[data-slot='carousel-previous'],
[data-slot='carousel-next'] {
  width: 30px !important;
  height: 30px !important;
}
[data-slot='separator'] {
  background: var(--border);
}

/* Toasts. Sonner keeps stacking, swipe, and timing; this layer owns the look.
   The html prefix outranks Sonner's injected stylesheet without !important. */
html [data-sonner-toaster] [data-sonner-toast][data-styled='true'] {
  align-items: center;
  gap: 12px;
  padding: 12px 44px 12px 12px;
  border: 0;
  border-radius: 16px;
  background: var(--popover);
  color: var(--popover-foreground);
  box-shadow:
    var(--overlay-shadow),
    0 24px 48px -24px rgba(28, 20, 10, 0.22);
  font-family: inherit;
}
html
  [data-sonner-toaster]
  [data-sonner-toast][data-styled='true']
  [data-content] {
  gap: 2px;
}
html
  [data-sonner-toaster]
  [data-sonner-toast][data-styled='true']
  [data-title] {
  font-size: 13px;
  font-weight: 600;
  line-height: 1.35;
  letter-spacing: -0.005em;
}
html
  [data-sonner-toaster]
  [data-sonner-toast][data-styled='true']
  [data-description] {
  font-size: 12px;
  line-height: 1.45;
  color: var(--muted-foreground);
}
html [data-sonner-toaster] [data-sonner-toast][data-styled='true'] [data-icon] {
  --chip: var(--muted-foreground);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 30px;
  height: 30px;
  margin: 0;
  border-radius: 10px;
  color: var(--chip);
  background: color-mix(in srgb, var(--chip) 12%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--chip) 16%, transparent);
}
html
  [data-sonner-toaster]
  [data-sonner-toast][data-styled='true']
  [data-icon]
  svg {
  width: 16px;
  height: 16px;
  margin: 0;
}
html
  [data-sonner-toaster]
  [data-sonner-toast][data-type='success']
  [data-icon] {
  --chip: var(--success);
}
html [data-sonner-toaster] [data-sonner-toast][data-type='error'] [data-icon] {
  --chip: var(--destructive);
}
html
  [data-sonner-toaster]
  [data-sonner-toast][data-type='warning']
  [data-icon] {
  --chip: var(--warning);
}
html [data-sonner-toaster] [data-sonner-toast][data-type='info'] [data-icon],
html [data-sonner-toaster] [data-sonner-toast][data-type='loading'] [data-icon],
html
  [data-sonner-toaster]
  [data-sonner-toast][data-promise='true']
  [data-icon] {
  --chip: var(--primary-bright);
}
html
  [data-sonner-toaster]
  [data-sonner-toast][data-styled='true']
  [data-button] {
  height: 28px;
  margin-left: auto;
  padding: 0 12px;
  border-radius: 99px;
  font-size: 12px;
  font-weight: 500;
  color: var(--background);
  background: var(--foreground);
  transition: transform 160ms var(--ease-out);
}
html
  [data-sonner-toaster]
  [data-sonner-toast][data-styled='true']
  [data-button]:active {
  transform: scale(0.97);
}
html
  [data-sonner-toaster]
  [data-sonner-toast][data-styled='true']
  [data-cancel] {
  color: var(--foreground);
  background: var(--secondary);
}
html
  [data-sonner-toaster]
  [data-sonner-toast][data-styled='true']
  [data-close-button] {
  left: auto;
  right: 10px;
  top: 50%;
  width: 26px;
  height: 26px;
  border: 0;
  border-radius: 8px;
  color: var(--muted-foreground);
  background: transparent;
  transform: translateY(-50%);
  transition:
    color var(--duration-quick) ease,
    background-color var(--duration-quick) ease,
    opacity var(--duration-quick) ease;
}
html
  [data-sonner-toaster]
  [data-sonner-toast][data-styled='true']
  [data-close-button]
  svg {
  width: 14px;
  height: 14px;
}
html
  [data-sonner-toaster]
  [data-sonner-toast][data-styled='true']
  [data-close-button]:hover,
html
  [data-sonner-toaster]
  [data-sonner-toast][data-styled='true']:hover
  [data-close-button]:hover {
  color: var(--foreground);
  background: var(--secondary);
  border: 0;
}
html
  [data-sonner-toaster]
  [data-sonner-toast][data-styled='true']
  [data-close-button]:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 1px;
  box-shadow: none;
}
@media (hover: hover) and (pointer: fine) {
  html
    [data-sonner-toaster]
    [data-sonner-toast][data-styled='true']
    [data-close-button] {
    opacity: 0;
  }
  html
    [data-sonner-toaster]
    [data-sonner-toast][data-styled='true']:hover
    [data-close-button],
  html
    [data-sonner-toaster]
    [data-sonner-toast][data-styled='true']
    [data-close-button]:focus-visible {
    opacity: 1;
  }
}
/* An action button sits where the close button would; keep them apart. */
html
  [data-sonner-toaster]
  [data-sonner-toast][data-styled='true']:has([data-button]) {
  padding-right: 44px;
}

/* Touch: buttons match the taller fields and reach a comfortable target,
   and the six OTP boxes tighten up to fit a phone-width card. */
@media (pointer: coarse) {
  [data-ui='button']:not([data-size^='icon']):not([data-size='sm']) {
    min-height: 42px;
    font-size: 14px;
  }
  [data-ui='button'][data-size='sm'] {
    min-height: 34px;
  }
  [data-ui='button'][data-size='icon'] {
    width: 40px;
    height: 40px;
  }
  [data-slot='input-otp-group'] {
    gap: 6px;
  }
}

/* iOS zooms the page when a focused field is under 16px. The field tokens
   cover the design-system inputs; this catches the remaining raw fields. */
@media (pointer: coarse) {
  [data-slot='command-input'],
  .composer textarea,
  input:not([data-slot]),
  textarea:not([data-slot]) {
    font-size: 16px !important;
  }
}

/* Keyframes */
@keyframes material-enter {
  from {
    opacity: 0;
    transform: translate(var(--enter-x), var(--enter-y)) scale(0.97);
    filter: blur(2px);
  }
  to {
    opacity: 1;
    transform: translate(0, 0) scale(1);
    filter: blur(0);
  }
}
@keyframes material-exit {
  to {
    opacity: 0;
    transform: scale(0.97);
  }
}
@keyframes dialog-enter {
  from {
    opacity: 0;
    scale: 0.96;
    translate: -50% calc(-50% + 8px);
    filter: blur(2px);
  }
  to {
    opacity: 1;
    scale: 1;
    translate: -50% -50%;
    filter: blur(0);
  }
}
@keyframes dialog-exit {
  to {
    opacity: 0;
    scale: 0.96;
    translate: -50% -50%;
  }
}
@keyframes sheet-in-right {
  from {
    transform: translateX(calc(100% + 16px));
  }
}
@keyframes sheet-out-right {
  to {
    transform: translateX(calc(100% + 16px));
  }
}
@keyframes tooltip-enter {
  from {
    opacity: 0;
    scale: 0.96;
  }
  to {
    opacity: 1;
    scale: 1;
  }
}
@keyframes fade-in {
  from {
    opacity: 0;
  }
}
@keyframes content-enter {
  from {
    opacity: 0;
    translate: 0 6px;
  }
  to {
    opacity: 1;
    translate: 0 0;
  }
}
@keyframes check-pop {
  from {
    opacity: 0;
    scale: 0.7;
  }
  to {
    opacity: 1;
    scale: 1;
  }
}
@keyframes skeleton-sheen {
  from {
    background-position: 100% 0;
  }
  to {
    background-position: -100% 0;
  }
}
@keyframes sheen {
  60%,
  100% {
    transform: translateX(100%);
  }
}

/* Motion preferences */
[data-motion='off'] *,
[data-motion='off'] *::before,
[data-motion='off'] *::after {
  animation-duration: 0.01ms !important;
  animation-iteration-count: 1 !important;
  transition-duration: 0.01ms !important;
  scroll-behavior: auto !important;
}
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
  }
  *,
  *::before,
  *::after {
    transition-property:
      opacity, color, background-color, border-color !important;
  }
}

.metal-button {
  border: 1px solid transparent !important;
  background:
    linear-gradient(var(--surface), var(--surface)) padding-box,
    conic-gradient(
        from 35deg,
        #7e7e82,
        #f4f4f7,
        #77777d,
        #e8e8eb,
        #606067,
        #f4f4f7,
        #7e7e82
      )
      border-box !important;
}
